document.querySelector('#cover-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>8*1024*1024){toast('Choose an image smaller than 8 MB.');return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Choose a JPEG, PNG or WebP image.');return;}try{const image=await createImageBitmap(file);const canvas=document.createElement('canvas'),scale=Math.min(1,1400/image.width);canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const imageUrl=canvas.toDataURL('image/jpeg',.82);image.close();openModal('Your own cover',`<form id="upload-form" data-image="${imageUrl}"><div class="upload-preview" style="background-image:url('${imageUrl}')"></div><label class="check-label">Crop position<input name="position" type="range" min="0" max="100" value="50" aria-label="Cover crop position"></label><label class="check-label">Lettering<select name="coverInk"><option value="#fff9ec">Ivory</option><option value="#273238">Charcoal</option><option value="#e4c18c">Warm gold</option></select></label><div class="modal-footer"><button class="primary" type="submit">Use this cover</button></div></form>`);document.querySelector('[name=position]').oninput=e=>document.querySelector('.upload-preview').style.backgroundPosition=e.target.value+'% center';}catch{toast('That image could not be opened. Try a JPEG or PNG.');}});
document.querySelector('#backup-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>15*1024*1024)throw Error('Backup is too large.');const parsed=JSON.parse(await file.text());validateBackup(parsed);confirmAction('Restore notebook?', 'This replaces the current notebook. A local saved copy will be kept, but export your current notebook first if you need it.',()=>{snapshot();state={...emptyState(),...parsed,settings:{...emptyState().settings,...parsed.settings}};storageCorrupt=false;noteId=state.notes[0]?.id||null;save();render();toast('Notebook restored.');});}catch(err){toast('Could not restore: '+err.message);}});
function validateBackup(data){if(data.bookmarks===undefined)data.bookmarks=[];if(!Array.isArray(data.bookmarks)||data.bookmarks.some(r=>!r||typeof r.name!=='string'||!/^[-a-zA-Z0-9]+$/.test(r.id)||!/^#[a-f0-9]{6}$/i.test(r.color)||!r.page||!/^\d{4}-\d{2}-\d{2}$/.test(r.page.date)||!['calendar','goals','tasks','notes','habits','reflection','launchpad'].includes(r.page.section)||!['day','week','month','year'].includes(r.page.view)))throw Error('Invalid bookmark ribbons.');if(data.version!==1)throw Error('Unsupported backup format.');for(const key of ['events','tasks','notes','habits','trash','cachedGoogle','googleCalendars'])if(!Array.isArray(data[key]))throw Error(`Missing ${key}.`);if(!data.entries||typeof data.entries!=='object'||Array.isArray(data.entries)||!data.settings||!data.ink)throw Error('Invalid notebook data.');for(const e of [...data.events,...data.cachedGoogle])if(typeof e.id!=='string'||typeof e.title!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(e.date))throw Error('Invalid appointment.');for(const t of data.tasks)if(typeof t.id!=='string'||typeof t.title!=='string')throw Error('Invalid task.');for(const n of data.notes)if(typeof n.id!=='string'||typeof n.title!=='string')throw Error('Invalid note.');for(const h of data.habits)if(typeof h.title!=='string'||!Array.isArray(h.checks))throw Error('Invalid habit.');for(const value of Object.values(data.entries))if(typeof value!=='string')throw Error('Invalid writing.');if(!Array.isArray(data.settings.favorites)||!Array.isArray(data.settings.selectedCalendars))throw Error('Invalid preferences.');if(data.settings.customCover&&!/^data:image\/(jpeg|png|webp);base64,[a-zA-Z0-9+/=]+$/.test(data.settings.customCover))throw Error('Invalid cover image.');if(!/^#[0-9a-fA-F]{6}$/.test(data.settings.ink)||data.settings.coverInk&&!/^#[0-9a-fA-F]{6}$/.test(data.settings.coverInk))throw Error('Invalid ink colour.');if(![...Array(coverNames.length).keys(),'custom'].includes(data.settings.cover))throw Error('Invalid cover.');data.settings.font='Caveat';}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
const reminded=new Set();function checkReminders(){const now=new Date();state.events.filter(e=>e.time&&e.reminder!==''&&e.reminder!=null&&eventOnDate(e,dateKey(now))).forEach(e=>{const start=new Date(`${dateKey(now)}T${e.time}`),due=start-Number(e.reminder)*60000,key=e.id+dateKey(now);if(now>=due&&now-due<60000&&!reminded.has(key)){reminded.add(key);toast(`Reminder: ${e.title} at ${e.time}`);}});}setInterval(checkReminders,30000);
