function attachWritingTools(root){
 root.querySelectorAll('textarea,input:not([type]),input[type="text"],input[type="search"]').forEach(field=>{
  if((section==='calendar'&&view==='week'&&root===app&&field.dataset.entry)||field.hasAttribute('data-no-writing-tools')||field.dataset.writingKey||field.closest('[inert]'))return;
  const key='writing-'+(++writingSequence);field.dataset.writingKey=key;
  const label=field.getAttribute('aria-label')||field.closest('label')?.firstChild?.textContent?.trim()||field.name||'this field';
  const controls=document.createElement('div');controls.className='write-tools field-write-tools';controls.innerHTML=`<button type="button" data-action="pencil" data-field-target="${key}" aria-label="Write with Pencil in ${esc(label)}">✎ Pencil</button><button type="button" data-action="dictate" data-field-target="${key}" aria-label="Dictate into ${esc(label)}">● Dictate</button>`;
  field.after(controls);
 });
}
